class OrderProcessor {
  private tempDiscount: number | null = null;
  process(order: any) {
    this.tempDiscount = this.calculateDiscount(order);
    order.total -= this.tempDiscount as number;
    this.tempDiscount = null;
  }
  private calculateDiscount(order: any) { return order.items.length * 1; }
}

class RequestHandler {
  private lastPayload: string | null = null;
  handle(request: any) {
    this.lastPayload = this.parse(request.body);
    const result = this.process(this.lastPayload);
    this.lastPayload = null;
    return result;
  }
  private parse(body: string) { return body.trim(); }
  private process(payload: string | null) { return payload?.toUpperCase() ?? ""; }
}

// Version A
class ReportBuilderA {
  private intermediate: string | null = null;
  build(data: any) {
    this.intermediate = this.prepare(data);
    const part = this.transform();
    return this.finalize(part);
  }
  private prepare(d: any) { return JSON.stringify(d); }
  private transform() { return this.intermediate ?? ""; }
  private finalize(p: string) { return p.length; }
}

// Version B
class ReportBuilderB {
  build(data: any) {
    const prepared = this.prepare(data);
    const part = this.transform(prepared);
    return this.finalize(part);
  }
  private prepare(d: any) { return JSON.stringify(d); }
  private transform(p: string) { return p; }
  private finalize(p: string) { return p.length; }
}
